export const SidebarMenubadge = "<script lang=\"ts\">\n\timport * as Sidebar from \"@stevejuma/ui/shadcn/sidebar\";\n\timport LifeBuoyIcon from \"@lucide/svelte/icons/life-buoy\";\n\timport SendIcon from \"@lucide/svelte/icons/send\";\n\timport FrameIcon from \"@lucide/svelte/icons/frame\";\n\timport ChartPieIcon from \"@lucide/svelte/icons/chart-pie\";\n\timport MapIcon from \"@lucide/svelte/icons/map\";\n\n\tconst projects = [\n\t\t{\n\t\t\tname: \"Design Engineering\",\n\t\t\turl: \"#\",\n\t\t\ticon: FrameIcon,\n\t\t\tbadge: \"24\",\n\t\t},\n\t\t{\n\t\t\tname: \"Sales & Marketing\",\n\t\t\turl: \"#\",\n\t\t\ticon: ChartPieIcon,\n\t\t\tbadge: \"12\",\n\t\t},\n\t\t{\n\t\t\tname: \"Travel\",\n\t\t\turl: \"#\",\n\t\t\ticon: MapIcon,\n\t\t\tbadge: \"3\",\n\t\t},\n\t\t{\n\t\t\tname: \"Support\",\n\t\t\turl: \"#\",\n\t\t\ticon: LifeBuoyIcon,\n\t\t\tbadge: \"21\",\n\t\t},\n\t\t{\n\t\t\tname: \"Feedback\",\n\t\t\turl: \"#\",\n\t\t\ticon: SendIcon,\n\t\t\tbadge: \"8\",\n\t\t},\n\t];\n</script>\n\n<Sidebar.Provider>\n\t<Sidebar.Root>\n\t\t<Sidebar.Content>\n\t\t\t<Sidebar.Group>\n\t\t\t\t<Sidebar.GroupLabel>Projects</Sidebar.GroupLabel>\n\t\t\t\t<Sidebar.GroupContent>\n\t\t\t\t\t<Sidebar.Menu>\n\t\t\t\t\t\t{#each projects as project (project.name)}\n\t\t\t\t\t\t\t<Sidebar.MenuItem>\n\t\t\t\t\t\t\t\t<Sidebar.MenuButton\n\t\t\t\t\t\t\t\t\tclass=\"group-has-[[data-state=open]]/menu-item:bg-sidebar-accent\"\n\t\t\t\t\t\t\t\t>\n\t\t\t\t\t\t\t\t\t{#snippet child({ props })}\n\t\t\t\t\t\t\t\t\t\t<a href={project.url} {...props}>\n\t\t\t\t\t\t\t\t\t\t\t<project.icon />\n\t\t\t\t\t\t\t\t\t\t\t<span>{project.name}</span>\n\t\t\t\t\t\t\t\t\t\t</a>\n\t\t\t\t\t\t\t\t\t{/snippet}\n\t\t\t\t\t\t\t\t</Sidebar.MenuButton>\n\t\t\t\t\t\t\t\t<Sidebar.MenuBadge>{project.badge}</Sidebar.MenuBadge>\n\t\t\t\t\t\t\t</Sidebar.MenuItem>\n\t\t\t\t\t\t{/each}\n\t\t\t\t\t</Sidebar.Menu>\n\t\t\t\t</Sidebar.GroupContent>\n\t\t\t</Sidebar.Group>\n\t\t</Sidebar.Content>\n\t</Sidebar.Root>\n</Sidebar.Provider>";
export const ControlledSidebar = "<script lang=\"ts\">\n\timport * as Sidebar from \"@stevejuma/ui/shadcn/sidebar\";\n\timport { Button } from \"@stevejuma/ui/shadcn/button\";\n\timport PanelLeftOpenIcon from \"@lucide/svelte/icons/panel-left-open\";\n\timport PanelLeftCloseIcon from \"@lucide/svelte/icons/panel-left-close\";\n\timport LifeBuoyIcon from \"@lucide/svelte/icons/life-buoy\";\n\timport SendIcon from \"@lucide/svelte/icons/send\";\n\timport FrameIcon from \"@lucide/svelte/icons/frame\";\n\timport ChartPieIcon from \"@lucide/svelte/icons/chart-pie\";\n\timport MapIcon from \"@lucide/svelte/icons/map\";\n\n\tconst projects = [\n\t\t{\n\t\t\tname: \"Design Engineering\",\n\t\t\turl: \"#\",\n\t\t\ticon: FrameIcon,\n\t\t},\n\t\t{\n\t\t\tname: \"Sales & Marketing\",\n\t\t\turl: \"#\",\n\t\t\ticon: ChartPieIcon,\n\t\t},\n\t\t{\n\t\t\tname: \"Travel\",\n\t\t\turl: \"#\",\n\t\t\ticon: MapIcon,\n\t\t},\n\t\t{\n\t\t\tname: \"Support\",\n\t\t\turl: \"#\",\n\t\t\ticon: LifeBuoyIcon,\n\t\t},\n\t\t{\n\t\t\tname: \"Feedback\",\n\t\t\turl: \"#\",\n\t\t\ticon: SendIcon,\n\t\t},\n\t];\n\n\tlet open = $state(true);\n</script>\n\n<Sidebar.Provider bind:open={() => open, (v) => (open = v)}>\n\t<Sidebar.Root>\n\t\t<Sidebar.Content>\n\t\t\t<Sidebar.Group>\n\t\t\t\t<Sidebar.GroupLabel>Projects</Sidebar.GroupLabel>\n\t\t\t\t<Sidebar.GroupContent>\n\t\t\t\t\t<Sidebar.Menu>\n\t\t\t\t\t\t{#each projects as project (project.name)}\n\t\t\t\t\t\t\t<Sidebar.MenuItem>\n\t\t\t\t\t\t\t\t<Sidebar.MenuButton>\n\t\t\t\t\t\t\t\t\t{#snippet child({ props })}\n\t\t\t\t\t\t\t\t\t\t<a href={project.url} {...props}>\n\t\t\t\t\t\t\t\t\t\t\t<project.icon />\n\t\t\t\t\t\t\t\t\t\t\t<span>{project.name}</span>\n\t\t\t\t\t\t\t\t\t\t</a>\n\t\t\t\t\t\t\t\t\t{/snippet}\n\t\t\t\t\t\t\t\t</Sidebar.MenuButton>\n\t\t\t\t\t\t\t</Sidebar.MenuItem>\n\t\t\t\t\t\t{/each}\n\t\t\t\t\t</Sidebar.Menu>\n\t\t\t\t</Sidebar.GroupContent>\n\t\t\t</Sidebar.Group>\n\t\t</Sidebar.Content>\n\t</Sidebar.Root>\n\t<Sidebar.Inset>\n\t\t<header class=\"flex h-12 items-center justify-between px-4\">\n\t\t\t<Button onclick={() => (open = !open)} size=\"sm\" variant=\"ghost\">\n\t\t\t\t{#if open}\n\t\t\t\t\t<PanelLeftCloseIcon />\n\t\t\t\t{:else}\n\t\t\t\t\t<PanelLeftOpenIcon />\n\t\t\t\t{/if}\n\t\t\t\t<span>{open ? \"Close\" : \"Open\"} Sidebar</span>\n\t\t\t</Button>\n\t\t</header>\n\t</Sidebar.Inset>\n</Sidebar.Provider>";
